import java.io.*;
import java.util.*;
public class Main {
 static class Fast {byte[] b=new byte[65536];int p,z;int read()throws Exception{if(p==z){z=System.in.read(b);p=0;if(z<0)return -1;}return b[p++];}int next()throws Exception{int c,v=0;do{c=read();}while(c<=32&&c>=0);while(c>32){v=v*10+c-48;c=read();}return v;}}
 static int[] freq,bucket,blockOf;static long[] sums;
 static void change(int id,int value,int delta){int f=freq[id];if(f>0){int old=bucket[f];bucket[f]^=value;sums[blockOf[f]]+=(long)bucket[f]-old;}f+=delta;freq[id]=f;if(f>0){int old=bucket[f];bucket[f]^=value;sums[blockOf[f]]+=(long)bucket[f]-old;}}
 public static void main(String[] args)throws Exception{Fast in=new Fast();int t=in.next();StringBuilder out=new StringBuilder();while(t-->0){int n=in.next();int[] a=new int[n],sorted=new int[n],ids=new int[n];for(int i=0;i<n;i++)sorted[i]=a[i]=in.next();Arrays.sort(sorted);for(int i=0;i<n;i++)ids[i]=Arrays.binarySearch(sorted,a[i]);int q=in.next();int[] ls=new int[q],rs=new int[q],xs=new int[q],ys=new int[q];long[] order=new long[q],ans=new long[q];int mo=Math.max(1,(int)(n/Math.sqrt(Math.max(1,q))));for(int i=0;i<q;i++){ls[i]=in.next()-1;rs[i]=in.next()-1;xs[i]=in.next();ys[i]=in.next();int b=ls[i]/mo,r=(b%2==0?rs[i]:n-1-rs[i]);order[i]=(((long)b*(n+1)+r)<<20)|i;}Arrays.sort(order);int bs=Math.max(1,(int)Math.sqrt(n));freq=new int[n];bucket=new int[n+1];blockOf=new int[n+1];sums=new long[n/bs+2];for(int i=0;i<=n;i++)blockOf[i]=i/bs;int l=0,r=-1;for(long key:order){int i=(int)(key&((1<<20)-1));while(l>ls[i]){--l;change(ids[l],a[l],1);}while(r<rs[i]){++r;change(ids[r],a[r],1);}while(l<ls[i]){change(ids[l],a[l],-1);l++;}while(r>rs[i]){change(ids[r],a[r],-1);r--;}int x=xs[i],y=Math.min(ys[i],r-l+1);long answer=0;while(x<=y&&x%bs!=0)answer+=bucket[x++];while(x+bs-1<=y){answer+=sums[x/bs];x+=bs;}while(x<=y)answer+=bucket[x++];ans[i]=answer;}for(long v:ans)out.append(v).append('\n');}System.out.print(out);}
}